DASHBOARD_HTML = r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veloikos Trading</title><style>:root{--b:#080b0a;--p:#101614;--l:#26362f;--t:#eef3ef;--m:#92a097;--g:#26d18e;--r:#ff6677;--a:#d8b866}*{box-sizing:border-box}body{margin:0;background:var(--b);color:var(--t);font:13px Arial,sans-serif}header{height:60px;padding:0 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--l)}.brand{font:700 23px Georgia}.brand b{font:10px Arial;letter-spacing:2px;color:var(--a);margin-left:6px}.live{color:var(--g);font-size:11px}.layout{display:grid;grid-template-columns:190px 1fr 280px;min-height:calc(100vh - 60px)}aside{padding:15px;border-right:1px solid var(--l)}.right{border-left:1px solid var(--l);border-right:0}main{padding:18px}.label{color:var(--m);font-size:10px;letter-spacing:1.4px;text-transform:uppercase}.watch{width:100%;text-align:left;background:none;color:var(--t);border:0;border-bottom:1px solid #1c2822;padding:13px 7px}.watch b{display:block}.ticker{display:flex;gap:18px;align-items:end;border-bottom:1px solid var(--l);padding-bottom:15px}.ticker h1{font-size:30px;margin:0}.price{font-size:25px;font-weight:bold}.quotes{margin-left:auto;display:flex;gap:20px}.quotes b{display:block;margin-top:5px}.chart{height:430px;border:1px solid var(--l);margin-top:14px;background:repeating-linear-gradient(0deg,#0d1411 0,#0d1411 71px,#1e2b25 72px)}.chart:after{content:'LIVE MARKET CHART';display:grid;place-items:center;height:100%;color:#425149;letter-spacing:3px}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.panel{background:var(--p);border:1px solid var(--l);padding:14px}.row{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid #1d2923}.row span{color:var(--m)}.grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--l)}.grid div{padding:13px;border:1px solid var(--l)}.grid b{display:block;font-size:18px;margin-top:6px}@media(max-width:900px){.layout{grid-template-columns:1fr}aside{display:none}.bottom{grid-template-columns:1fr}.quotes{display:none}}</style></head><body><header><div class="brand">Veloikos <b>TRADING</b></div><div class="live">LIVE EXECUTION ACTIVE</div></header><div class="layout"><aside><div class="label">Watchlist</div><div id="watch"></div></aside><main><div class="ticker"><div><div class="label">Selected instrument</div><h1>SPY</h1></div><div><div class="price">Live market</div><span class="live">Broker connected</span></div><div class="quotes"><div class="label">Bid<b>--</b></div><div class="label">Ask<b>--</b></div><div class="label">Spread<b>--</b></div></div></div><div class="chart"></div><div class="bottom"><section class="panel"><b>Open positions</b><div id="pos" class="row">Loading...</div></section><section class="panel"><b>Execution activity</b><div id="act" class="row">Loading...</div></section></div></main><aside class="right"><div class="label">Live account</div><div class="grid"><div><span class="label">Equity</span><b id="eq">$--</b></div><div><span class="label">Buying power</span><b id="bp">$--</b></div><div><span class="label">Positions</span><b id="ct">0</b></div><div><span class="label">Market</span><b id="mk">--</b></div></div></aside></div><script>const syms=['SPY','QQQ','IWM','NVDA','AAPL','MSFT','GLD','TLT'];document.querySelector('#watch').innerHTML=syms.map(s=>'<button class="watch"><b>'+s+'</b><span>Live market data</span></button>').join('');const money=x=>'$'+Number(x||0).toFixed(2);async function r(){let[p,a]=await Promise.all([fetch('/brokers/alpaca/live-portfolio').then(x=>x.json()),fetch('/live/activity').then(x=>x.json())]),b=p.balances||{},z=p.positions||[];eq.textContent=money(b.equity);bp.textContent=money(b.buying_power);ct.textContent=z.length;mk.textContent=p.market_clock?.is_open?'OPEN':'CLOSED';pos.innerHTML=z.map(x=>'<b>'+x.symbol+'</b><span>'+x.qty+' shares</span>').join('')||'No open live positions.';act.innerHTML=(a.events||[]).slice(0,4).map(x=>'<div class="row"><b>'+x.type+'</b><span>'+new Date(x.timestamp+'Z').toLocaleTimeString()+'</span></div>').join('')||'No live events yet.'}r();setInterval(r,5000)</script></body></html>'''